Q: Anonymous Promises
A: <p>If you your use case is to wrap function execution with a promise (to catch errors) you could do something like the code below. </p>

<p>You only need 1 <code>catch</code> function to handle errors in the entire chain. Try removing the comments and see how it behaves.</p>

<p>See also the <code>promisify</code> function which provides a nicer API in my opinion.</p>

<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="true">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function promiseThis(doThis, withThis, task) {
  return new Promise((resolve, reject) =&gt; {
    const result = doThis(withThis);
    if (result) {
      resolve(result)
    } else {
      reject(`can't do task: ${task}`)
    }
  })
}

function print(name) {
  // throw Error('printing error!');
  console.log(name);
  return name;
}

function capitalizeName(name) {
  // throw Error('error capitalizing?!');
  return name.toUpperCase();
}


fetch('https://randomuser.me/api/')
  .then(response =&gt; response.json())
  .then(json =&gt; promiseThis(print, json.results[0].email))
  .then(email =&gt; promiseThis(capitalizeName, email))
  .then(email =&gt; promiseThis(print, email))
  .then(() =&gt; promiseThis(print, 'I can ignore the incoming value'))
  .catch(e =&gt; console.error(e))

// You can achieve a nicer API like this
function getEmail(json) {
  return json.results[0].email
